Hier ist ein Beispiel-Code für ein C++ Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string wordToCount; // Wort, das gezählt werden soll
    std::string line;         // Zeile aus der Datei
    int count = 0;            // Anzahl der Vorkommen des Wortes

    // Wort einlesen, welches gezählt werden soll
    std::cout << "Geben Sie das Wort ein, das gezählt werden soll: ";
    std::cin >> wordToCount;

    std::ifstream inputFile("input.txt"); // Dateiname anpassen

    if (!inputFile) {
        std::cerr << "Datei konnte nicht geöffnet werden!" << std::endl;
        return 1;
    }

    while (getline(inputFile, line)) { // Zeilen aus Datei lesen
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != std::string::npos) { // Wort suchen in Zeile
            ++count; // Wort gefunden, Anzahl erhöhen
            pos += wordToCount.length(); // Position für nächsten Suchversuch setzen
        }
    }

    inputFile.close();

    std::cout << "Das Wort \"" << wordToCount << "\" kommt " << count << " Mal in der Datei vor." << std::endl;

    return 0;
}
